const BULAN_PANJANG = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const tglPanjang = s => { const a = String(s || '').match(/^(\d{1,2})-(\d{1,2})-(\d{4})$/); if (a) return (+a[1]) + ' ' + BULAN_PANJANG[+a[2] - 1] + ' ' + a[3]; const b = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return b ? (+b[3]) + ' ' + BULAN_PANJANG[+b[2] - 1] + ' ' + b[1] : ''; };
// Cara bayar singkat per metode (panduan lengkap tetap ada di halaman TriPay)
const CARA = {
  BRIVA: 'buka BRImo, pilih menu BRIVA, masukkan nomor VA di atas, cek nama dan total, lalu bayar.',
