};

const memo = $getWorkflowStaticData('global');
memo.trx = memo.trx || {};
const now = Date.now();
for (const [kunci, v] of Object.entries(memo.trx)) if (!v || !v.exp || v.exp < now) delete memo.trx[kunci];

const keluar = [];
// v39: API kirim pesan MobiChat yang baru: POST /api/public/messages, body { conversation_id, messages: [ ... ] }
// (endpoint lama /api/bot/reply dan /api/bot/reply/media diganti sesuai arahan tim MobiChat, 29 Okt 2026)
const URL_KIRIM = MOBICHAT + '/api/public/messages';
const teks = (msg, tambahan) => keluar.push({ json: { conversation_id: cid, url: URL_KIRIM, kirim: { conversation_id: Number(cid), messages: [{ message_type: 'text', text: String(msg) }] }, ...(tambahan || {}) } });
const gagalKirim = (t, gagal) => teks('Maaf Kak, kode pembayaran untuk tagihan ' + t.periode + ' belum berhasil dibuat otomatis 🙏\n\nKakak bisa bayar langsung lewat link ini ya (pilih *QRIS* ya, bisa discan dari aplikasi bank atau e-wallet apa saja):\n'
  + (t.billing_url || BILLING) + '/checkout/payment?invoice=' + t.invoice + '&noservices=' + t.id_pelanggan
  + '\n\nTim kami juga sudah kami kabari untuk bantu cek 😊', { gagal, invoice: t.invoice });

// v45c: DNS / jaringan VM n8n kadang gagal sesaat (12 Nov 20.27: "getaddrinfo EAI_AGAIN billing.btd.co.id" -> QRIS gagal dibuat).
// Checkout billing diulang (maks. 3x, jeda 1,5 lalu 3 detik) HANYA bila permintaan belum sempat terkirim (DNS / koneksi ditolak),
// supaya tidak membuat transaksi TriPay ganda. Membaca halaman TriPay aman diulang untuk semua galat jaringan sesaat.
const teksGalat = e => String((e && (e.code || e.message)) || e);
const belumTerkirim = e => /EAI_AGAIN|ENOTFOUND|ECONNREFUSED|EHOSTUNREACH|ENETUNREACH/i.test(teksGalat(e));
const galatSesaat = e => belumTerkirim(e) || /ETIMEDOUT|ECONNRESET|ESOCKETTIMEDOUT|socket hang up|timeout/i.test(teksGalat(e));
const coba = async (fn, bolehUlang) => { for (let i = 1; ; i++) { try { return await fn(); } catch (e) { if (i >= 3 || !bolehUlang(e)) throw e; await new Promise(r => setTimeout(r, 1500 * i)); } } };
// 1) Checkout di billing (sama seperti tombol "Checkout Sekarang") + baca detail dari halaman TriPay
const siap = [];
for (const t of bayar) {
  try {
    const awalan = t.billing && t.billing !== 'SKY' ? t.billing + ':' : ''; // nomor invoice bisa sama di billing mitra
    const kunci = awalan + t.invoice + '|' + t.metode;
    const lama = memo.trx[kunci];
    let ref = (lama && lama.exp > now + 5 * 60e3) ? lama.ref : '';
    let linkLangsung = (lama && lama.exp > now + 5 * 60e3 && lama.link) ? lama.link : ''; // e-wallet (DANA dll.) yang langsung diarahkan ke aplikasinya
    const baru = !ref;
    let gagal = '';
    if (!ref) {
      try {
        const r = await coba(() => http.httpRequest({
          method: 'POST', url: (t.billing_url || BILLING) + '/tripay/checkout', timeout: 20000, json: false,
          headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': UA },
          body: formBody({ invoice: t.invoice, no_services: t.id_pelanggan, amount: String(t.total), codecoupontripay: '', disccoupontripay: '0', selectpaymenttripay: t.metode })
        }), belumTerkirim);
        const h = teksDari(r);
        ref = (h.match(/tripay\.co\.id\/checkout\/([A-Z0-9]+)/i) || [])[1] || '';
        // DANA/e-wallet: billing langsung mengarahkan ke halaman bayar aplikasinya (window.location='https://m.dana.id/...')
        const arah = (h.match(/(?:window\.)?location(?:\.href)?\s*=\s*['"](https:\/\/[^'"\s]+)['"]/i) || [])[1] || '';
        if (!ref && arah && !/tripay\.co\.id/i.test(arah) && /^(OVO|DANA|SHOPEEPAY|LINKAJA|GOPAY)$/i.test(t.metode)) { linkLangsung = arah.replace(/&amp;/g, '&'); ref = 'EW' + t.invoice + '-' + now; }
        if (!ref) gagal = 'Checkout billing tanpa link TriPay: ' + bersih(h).slice(0, 200);
      } catch (e) {
        gagal = 'Checkout billing error: ' + String((e && e.message) || e).slice(0, 200);
      }
    }
    let d = {};
    if (linkLangsung && !gagal) d = { jumlah: Number(t.total) || 0, metode: t.nama_metode || t.metode, link_langsung: linkLangsung, tanpa_biaya: true };
    else if (ref && !gagal) {
      try {
        const r = await coba(() => http.httpRequest({ method: 'GET', url: 'https://tripay.co.id/checkout/' + ref, timeout: 20000, json: false, headers: { 'User-Agent': UA } }), galatSesaat);
        d = bacaHalamanTripay(teksDari(r));
