    const exp = (lama && lama.ref === ref && lama.exp) || Date.parse(String(d.kedaluwarsa_utc || '').replace(' ', 'T') + 'Z') || (now + 25 * 60e3);
    memo.trx[kunci] = { ref, exp, conversation_id: cid, dibuat: lama && lama.ref === ref ? lama.dibuat : now, link: linkLangsung || '' };
