}

// 3) Pesan tagihan + pembayaran bergaya kartu (teks WhatsApp: *tebal*, emoji, berbagian), link hanya bila perlu
const GARIS = '━━━━━━━━━━━━━━━';
const angkaEmoji = ['1️⃣', '2️⃣', '3️⃣', '4️⃣'];
// kalimat pembuka bergiliran per percakapan supaya tidak sama terus
memo.pembukaBayar = (memo.pembukaBayar && Object.keys(memo.pembukaBayar).length < 1000) ? memo.pembukaBayar : {};
const pilihPembuka = (daftar) => { const lalu = memo.pembukaBayar[cid]; let i = Math.floor(Math.random() * daftar.length); if (daftar.length > 1 && i === lalu) i = (i + 1) % daftar.length; memo.pembukaBayar[cid] = i; return daftar[i]; };
const PEMBUKA_QRIS = ['Siap Kak, ini tagihan dan QRIS-nya ya 🙏', 'Ini rincian tagihannya beserta QRIS, Kak 😊', 'Sudah kami siapkan QRIS-nya ya Kak, tinggal scan 👇', 'Berikut tagihan internetnya ya Kak 🙏', 'Oke Kak, QRIS-nya sudah jadi 😊'];
const PEMBUKA_LAIN = ['Siap Kak, ini tagihan dan kode bayarnya ya 🙏', 'Ini rincian tagihannya ya Kak 😊', 'Sudah kami buatkan pembayarannya, Kak 🙏', 'Oke Kak, kode bayarnya sudah jadi 👇'];
const bagian = (judul, isi) => [judul, ...isi.filter(Boolean)].join('\n');
for (const { t, ref, d, exp } of siap) {
