  const adaLink = adaLinkBilling(ref);
  const qris = t.metode === 'QRIS2' || t.metode === 'QRIS';
  const namaMetode = d.metode || t.nama_metode || t.metode;
  const jt = tglPanjang(t.jatuh_tempo);
  const mitra = !!(t.billing && t.billing !== 'SKY');
  const info = { invoice: t.invoice, ref, metode: t.metode, total_bayar: d.jumlah, link_billing_terdeteksi: adaLink,
    billing: t.billing || 'SKY', billing_url: t.billing_url || BILLING, periode: t.periode || '', sn: String(t.id_pelanggan || ''), nama: t.nama || '', exp };
  const kepala = [
    '🧾 *TAGIHAN INTERNET' + (mitra ? '' : ' SKY TECH') + '*',
    GARIS,
    bagian('👤 *Pelanggan*', [t.id_pelanggan ? '• ID: ' + t.id_pelanggan : '', '• Nama: ' + t.nama]),
    '',
    bagian('📅 *Rincian Tagihan*', ['• Periode: ' + t.periode, jt ? '• Jatuh tempo: ' + jt : '', '• Tagihan: ' + rupiah(t.total)])
  ];
  // penjelasan struk: bayar lewat kode/QR ini otomatis tercatat; transfer manual ke rekening wajib kirim struk (nomor rekening tidak ditampilkan)
  const penutup = lewat => bagian('📌 *Penting ya Kak*', [
    '• Bayar lewat ' + lewat + ' ini: tercatat otomatis, *tidak perlu kirim struk* 🙏',
    '• Kalau bayarnya *transfer manual ke rekening*, mohon *kirim foto struknya* di chat ini (tanggal, jam, dan nominal terlihat) supaya bisa kami cocokkan.'
  ]);
  if (qris) {
    const isi = [pilihPembuka(PEMBUKA_QRIS), '', ...kepala, '',
      bagian('💳 *Pembayaran via QRIS*', ['• Total bayar: *' + rupiah(d.jumlah) + '*', '• Berlaku sampai: ' + jamWib(exp)]), '',
      bagian('📲 *Cara Bayar*', [angkaEmoji[0] + ' Simpan gambar QR ini', angkaEmoji[1] + ' Buka BRImo, DANA, GoPay, OVO, ShopeePay, atau m-banking lain', angkaEmoji[2] + ' Pilih *Scan / QRIS*, ambil gambar dari galeri, lalu bayar']),
      ...(adaLink ? ['', '🔗 Bisa juga lewat tombol bayar di *link pembayaran otomatis* di atas.'] : []),
      '', penutup('QRIS')];
    let caption = isi.join('\n');
    if (caption.length > 1000) caption = isi.filter(x => !/Cara Bayar|1️⃣|2️⃣|3️⃣/.test(x)).join('\n').replace(/\n{3,}/g, '\n\n');
    keluar.push({ json: { conversation_id: cid, url: URL_KIRIM, kirim: {
      conversation_id: Number(cid), messages: [{ message_type: 'media', media_url: 'https://tripay.co.id/qr/' + ref, media_type: 'image', text: caption.slice(0, 1024), caption: caption.slice(0, 1024) }]
    }, ...info } });
    if (!adaLink) teks('🔗 Kalau QR-nya susah discan, bisa bayar lewat link ini ya Kak:\n' + link, info);
  } else if (d.link_langsung) {
    // e-wallet langsung (DANA dll.): satu tautan menuju aplikasinya
    const isi = [pilihPembuka(PEMBUKA_LAIN), '', ...kepala, '',
