      bagian('📲 *Cara Bayar*', [angkaEmoji[0] + ' Tekan link ini, nanti terbuka aplikasi ' + namaMetode + ':\n' + link, angkaEmoji[1] + ' Cek nama dan total, lalu bayar', angkaEmoji[2] + ' Link hanya berlaku sebentar; kalau sudah tidak bisa dibuka, minta dibuatkan lagi di chat ini']), '',
