    else if (vaLike) cara = [angkaEmoji[0] + ' Buka m-banking atau ATM, pilih menu *Virtual Account*', angkaEmoji[1] + ' Masukkan nomor VA di atas', angkaEmoji[2] + ' Cek nama dan total, lalu bayar'];
    const isi = [pilihPembuka(PEMBUKA_LAIN), '', ...kepala, '',
      bagian(ikon + ' *Pembayaran via ' + namaMetode + '*', [d.kode_bayar && !ewallet ? '• ' + labelKode + ': *' + d.kode_bayar + '*' : '', '• Total bayar: *' + rupiah(d.jumlah) + '*', '• Berlaku sampai: ' + jamWib(exp)]), '',
      bagian('📲 *Cara Bayar*', cara),
      ...(!pakaiLink ? ['', adaLink ? '📘 Panduan lengkapnya ada di *link pembayaran otomatis* di atas ya.' : '📘 Panduan lengkap: ' + link] : []),
      '', penutup(vaLike ? 'nomor VA' : gerai ? 'kode bayar' : namaMetode)];
    teks(isi.join('\n'), info);
  }
}
return keluar;

