const memo = $getWorkflowStaticData('global');
memo.kontak = memo.kontak || {};
for (const [x, v] of Object.entries(memo.kontak)) if (!v || now - (v.t || 0) > 120 * 864e5) delete memo.kontak[x];
const catat = memo.kontak[cid] = memo.kontak[cid] || { lapor: {} };
catat.t = now; catat.lapor = catat.lapor || {};
memo.nomorBaru = memo.nomorBaru || {};
memo.gantiHp = memo.gantiHp || {};
for (const [x, v] of Object.entries(memo.gantiHp)) if (!v || now - v > 30 * 864e5) delete memo.gantiHp[x];

const lokal = x => String(x || '').replace(/\D/g, '').replace(/^62/, '').replace(/^0/, '');
const hp = x => { const l = lokal(x); return l ? ('0' + l).replace(/^(\d{4})(\d{4})(\d+)$/, '$1-$2-$3') : '-'; };
const wa = lokal(kt.wa);
const semua = s.profil || [];
const aktif = semua.filter(p => !/free/i.test(String(p.status || '')));
const lewat = (p, re) => (p.sumber || []).some(x => re.test(x));
const kuat = p => lewat(p, /nomor WhatsApp pelanggan ini|pesan tagihan billing|nomor baru yang sudah diverifikasi/i);
const dasar = p => lewat(p, /nomor WhatsApp pelanggan ini/i) ? 'nomor WhatsApp ini terdaftar di billing'
