// ID yang sama bisa ada di billing Sky Tech dan billing mitra: pilih yang kuat (nomor WA / pesan tagihan), lalu yang terverifikasi
const cariSn = sn => { const c = semua.filter(x => String(x.sn) === String(sn) && !x.ganda); return c.find(kuat) || c.find(x => x.terverifikasi) || c[0]; };
const lb = p => (p && p.billing && p.billing !== 'SKY') ? ' [billing ' + (p.billing_nama || p.billing) + ']' : '';
const ik = b.info_kontak || null;
const jawab = id => (ik && String(ik.id_pelanggan) === String(id) && typeof ik.nomor_lama_dipakai === 'boolean') ? String(ik.nomor_lama_dipakai) : '-';
