  if (st !== 'VALID') memo.laporStruk.push({ st, id, nama: kolom['NAMA PELANGGAN'], wa: angka(kolom['NO WA PELANGGAN']), cid: angka(kolom['ID PERCAKAPAN MOBICHAT']), inv: angka(kolom['NO INVOICE']), bulan: kolom['BULAN TAGIHAN'], nominal: angka(kolom.NOMINAL), tgl: kolom['TANGGAL TRANSFER'], jam: kolom['JAM TRANSFER'], rek: kolom['REKENING TUJUAN'], pengirim: kolom['BANK DAN NAMA PENGIRIM'], ket: kolom['KETERANGAN AI'] });
}
memo.gagalBacaSheet = gagalBaca ? String(gagalBaca.error).slice(0, 200) : '';
