if (!data.length) { try { data = $('Cek duplikat struk').all().map(i => i.json || {}); } catch (e) { data = []; } }
const rupiah = n => 'Rp' + String(Math.round(Number(String(n || '').replace(/\D/g, '')) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const bersih = x => String(x == null ? '' : x).replace(/^'/, '').trim();
const e0 = items[0].error;
const pesan = String((e0 && (e0.message || e0)) || items[0].message || 'tidak diketahui').slice(0, 300);
