  ? 'Judul kolom di baris 1 lembar "STRUK AI CS" tidak sama dengan kolom yang dikirim n8n (ada kolom yang dihapus, diganti nama, atau belum ditambahkan). Samakan judul kolomnya (baris 1 harus sampai T1: R1 STATUS STRUK, S1 NO REFERENSI, T1 SIDIK FOTO), lalu struk berikutnya tercatat lagi.'
  : 'kredensial Google, izin Editor di Sheet, nama lembar berubah, kuota Google, atau gangguan Google.';
const GARIS = '━━━━━━━━━━━━━━━━━━';
const blok = data.slice(0, 5).map(x => [
  '🧾 ' + (bersih(x['NAMA PELANGGAN']) || '-') + ' (ID ' + (bersih(x['ID PELANGGAN']) || '-') + ')',
  '• Invoice: ' + (bersih(x['NO INVOICE']) || '-') + (x['BULAN TAGIHAN'] ? ' (' + bersih(x['BULAN TAGIHAN']) + ')' : ''),
  '• Nominal: ' + rupiah(x.NOMINAL),
  '• Waktu transfer: ' + ((bersih(x['TANGGAL TRANSFER']) + ' ' + bersih(x['JAM TRANSFER'])).trim() || '-'),
  '• Jenis: ' + ((bersih(x['JENIS PEMBAYARAN']) + ' ' + bersih(x['REKENING TUJUAN'])).trim() || '-'),
