// GANTI NOMOR HP PELANGGAN DI BILLING (mode GANTI_NOMOR_BILLING = 'otomatis'), input dari node "Cek data kontak"
// Pengaman:
//   1) data pelanggan dibaca dulu; nomor di billing harus masih sama dengan nomor lama yang diverifikasi
//   2) semua isian pelanggan dikirim ulang apa adanya, hanya nomor HP yang diganti (PUT /customers/{id})
//   3) dibaca ulang: nomor harus sudah berubah dan nama, email, NIK, alamat TIDAK boleh ikut berubah;
//      v44: SEMUA isian lain di data pelanggan (termasuk data layanan seperti ODC / ODP / coverage / paket) ikut dibandingkan sebelum-sesudah,
//      dan bila ada yang ikut berubah / hilang langsung dilaporkan 🚨 ke Telegram beserta nilai lamanya supaya bisa dikembalikan
//   4) hasil (berhasil / gagal / ada data yang berubah) selalu dikabarkan ke grup Telegram
const d = $input.first().json || {};
const g = d.ganti_hp || {};
const memo = $getWorkflowStaticData('global');
const http = (typeof helpers !== 'undefined' && helpers.httpRequest) ? helpers : this.helpers;
// billing tempat pelanggan terdaftar: Sky Tech atau billing mitra (Surya/Bayu, aplikasi yang sama)
const mitra = !!(g.billing && g.billing !== 'SKY');
const API = String(g.billing_url || 'https://billing.btd.co.id').replace(/\/+$/, '') + '/api/v1';
let token = '';
if (mitra) { const tm = (memo.tokenMitra || {})[g.billing]; token = (tm && tm.token && tm.exp > Date.now()) ? tm.token : ''; }
else {
  token = (memo.billingToken && memo.billingToken.token) || '';
  try { if (!token) token = (($('Token billing').first() || {}).json || {}).token || ''; } catch (e) { /* node tidak ada */ }
}
const lokal = x => String(x || '').replace(/\D/g, '').replace(/^62/, '').replace(/^0/, '');
const hp = x => { const l = lokal(x); return l ? ('0' + l).replace(/^(\d{4})(\d{4})(\d+)$/, '$1-$2-$3') : '-'; };
const link = 'https://app.mobichat.id/inbox?id=' + (g.cid || d.conversation_id || '');
// ---- format laporan Telegram: judul + garis + bagian berjudul emoji (teks biasa, tanpa Markdown)
const GARIS = '━━━━━━━━━━━━━━━━━━';
const waktuWib = () => { const t = new Date(Date.now() + 7 * 3600e3).toISOString(); return t.slice(8, 10) + '/' + t.slice(5, 7) + '/' + t.slice(0, 4) + ' ' + t.slice(11, 16) + ' WIB'; };
const HUB = { pemilik: 'pemilik layanan', keluarga_serumah: 'keluarga serumah', orang_lain: 'orang lain', belum_jelas: 'belum jelas' };
const bagian = (judul, ...isi) => ({ judul, isi: isi.filter(Boolean) });
const susun = (judul, daftar) => [judul + '\n' + GARIS, ...daftar.filter(b => b && b.isi.length).map(b => b.judul + '\n' + b.isi.map(x => '• ' + x).join('\n')), '🕒 ' + waktuWib() + '\n💬 ' + link].join('\n\n').slice(0, 3800);
const bPelanggan = () => bagian('👤 Pelanggan', 'ID: ' + g.sn, 'Nama: ' + (g.nama || '-'), 'Billing: ' + (g.billing_nama || 'Sky Tech'));
const bNomor = berhasil => bagian('📱 Nomor WhatsApp', 'Lama: ' + hp(g.lama) + (berhasil ? ' ➜ diganti' : ''), 'Baru: ' + hp(g.baru) + (berhasil ? ' ✅' : ''));
const bVerif = () => bagian('🔐 Verifikasi AI', 'Dasar: ' + (g.dasar || '-'), g.hubungan ? 'Pengirim: ' + (HUB[g.hubungan] || g.hubungan) : '');
const bKontak = () => bagian('📇 Kontak MobiChat', g.nama_kontak ? 'Nama kontak ikut diganti ke ' + g.nama_kontak + ' (bila gagal, ada laporan ❌ terpisah)' : 'Nama kontak tidak diubah');
const kirim = (judul, ...tambahan) => [{ json: { telegram: susun(judul, [bPelanggan(), ...tambahan]) } }];
const gagal = alasan => kirim('⚠️ GANTI NOMOR GAGAL — MOHON DIGANTI MANUAL', bNomor(false), bVerif(), bagian('❗ Penyebab', String(alasan).slice(0, 300)), bagian('🛠️ Tindakan tim', 'Ganti nomor HP pelanggan secara manual di billing ' + (g.billing_nama || 'Sky Tech')), bKontak());
if (!g.cust || !lokal(g.baru)) return [];
if (!token) return gagal('token billing kosong');

const panggil = async (method, path, body, jenis) => {
  const opsi = { method, url: API + path, headers: { Authorization: 'Bearer ' + token, Accept: 'application/json' }, ignoreHttpStatusErrors: true, returnFullResponse: true, timeout: 25000 };
  if (body && jenis === 'form') { opsi.body = Object.keys(body).map(kk => encodeURIComponent(kk) + '=' + encodeURIComponent(String(body[kk] == null ? '' : body[kk]))).join('&'); opsi.headers['Content-Type'] = 'application/x-www-form-urlencoded'; }
  else if (body) { opsi.body = body; opsi.json = true; }
  else opsi.json = true;
  try {
    const r = await http.httpRequest(opsi);
    let isi = r.body; if (typeof isi === 'string') { try { isi = JSON.parse(isi); } catch (e) { /* teks */ } }
    return { kode: r.statusCode, isi };
  } catch (e) { return { kode: 'ERR', isi: String(e.message || e) }; }
};
const baca = async () => { const r = await panggil('GET', '/customers/' + encodeURIComponent(g.cust)); return r.kode === 200 && r.isi && r.isi.data ? r.isi.data : null; };

// 1) data sekarang
const awal = await baca();
if (!awal) return gagal('data pelanggan (customer id ' + g.cust + ') tidak bisa dibaca');
const snAda = [awal.service_number, awal.service && awal.service.service_number, ...((awal.services || []).map(x => x.service_number))].map(String).includes(String(g.sn));
if (!snAda) return gagal('ID layanan ' + g.sn + ' tidak ada di data pelanggan ' + g.cust);
const hpAwal = /^(\+?62|0)/.test(String(awal.phone || '')) ? lokal(awal.phone) : lokal((awal.phone_code || '') + (awal.phone || ''));
if (hpAwal === lokal(g.baru)) return kirim('ℹ️ NOMOR DI BILLING SUDAH SESUAI (tidak diubah)', bNomor(false), bVerif(), bKontak());
if (lokal(g.lama) && hpAwal !== lokal(g.lama)) return gagal('nomor di billing sekarang ' + hp(hpAwal) + ', bukan nomor lama yang diverifikasi (mungkin sudah diubah tim)');
if (!awal.name || !awal.email) return gagal('nama atau email pelanggan kosong di billing (wajib untuk update lewat API)');

// 2) kirim ulang semua isian apa adanya, hanya nomor HP yang diganti (format mengikuti data lama)
const pakai0 = String(awal.phone || '').startsWith('0'), pakai62 = /^(\+?62)/.test(String(awal.phone || ''));
const nomor = pakai0 ? '0' + lokal(g.baru) : pakai62 ? '62' + lokal(g.baru) : lokal(g.baru);
const isian = { name: awal.name, email: awal.email, phone: nomor, phone_code: awal.phone_code == null ? '' : awal.phone_code };
for (const kk of ['customer_type_id', 'id_type_id', 'id_number', 'birth_date', 'address', 'description']) if (awal[kk] != null && awal[kk] !== '') isian[kk] = awal[kk];
const percobaan = [];
let ok = false;
for (const jenis of ['form', 'json']) {
  const r = await panggil('PUT', '/customers/' + encodeURIComponent(g.cust), isian, jenis);
  percobaan.push(jenis + ' ' + r.kode + ' ' + JSON.stringify(r.isi).slice(0, 160));
  if (typeof r.kode === 'number' && r.kode >= 200 && r.kode < 300) { ok = true; break; }
  if (!(r.kode === 400 || r.kode === 422)) break; // hanya coba format lain bila ditolak validasi (tidak ada yang tersimpan)
}
if (!ok) return gagal('billing menolak: ' + percobaan.join(' | '));

// 3) baca ulang dan pastikan hanya nomor yang berubah
const akhir = await baca();
if (!akhir) return kirim('⚠️ NOMOR SUDAH DIKIRIM KE BILLING, HASIL BELUM BISA DICEK ULANG', bNomor(false), bVerif(), bagian('🛠️ Tindakan tim', 'Cek nomor HP pelanggan di billing ' + (g.billing_nama || 'Sky Tech')), bKontak());
const hpAkhir = /^(\+?62|0)/.test(String(akhir.phone || '')) ? lokal(akhir.phone) : lokal((akhir.phone_code || '') + (akhir.phone || ''));
const berubah = ['name', 'email', 'id_number', 'address', 'customer_type_id', 'birth_date'].filter(kk => String(awal[kk] == null ? '' : awal[kk]) !== String(akhir[kk] == null ? '' : akhir[kk]));
// v44: bandingkan seluruh isi data pelanggan (sampai 5 tingkat), kecuali nomor HP dan cap waktu
const ratakan = (o, awalan, out, dalam) => { if (o == null || typeof o !== 'object') { out[awalan] = o == null ? '' : String(o); return out; } if (dalam > 5) return out; for (const kk of Object.keys(o).slice(0, 80)) { if (/^(phone|phone_code|whatsapp|wa|updated_at|created_at|last_\w+|\w+_at|token|password|uptime|\w*online\w*|\w*(bytes|usage|traffic|session|ping|signal|rx_|tx_)\w*)$/i.test(kk)) continue; ratakan(o[kk], awalan ? awalan + '.' + kk : kk, out, dalam + 1); } return out; };
const rA = ratakan(awal, '', {}, 0), rZ = ratakan(akhir, '', {}, 0);
const lain = [...new Set([...Object.keys(rA), ...Object.keys(rZ)])].filter(kk => !berubah.includes(kk) && String(rA[kk] == null ? '' : rA[kk]) !== String(rZ[kk] == null ? '' : rZ[kk])).slice(0, 12);
memo.gantiHpHasil = memo.gantiHpHasil || [];
memo.gantiHpHasil.push({ t: Date.now(), sn: g.sn, b: g.billing || 'SKY', cust: g.cust, lama: hpAwal, baru: hpAkhir, berubah: berubah.concat(lain) });
memo.gantiHpHasil = memo.gantiHpHasil.slice(-200);
const NAMA_ISIAN = { name: 'nama', email: 'email', id_number: 'NIK', address: 'alamat', customer_type_id: 'tipe pelanggan', birth_date: 'tanggal lahir' };
if (berubah.length || lain.length) return kirim('🚨 NOMOR DIGANTI, TAPI DATA LAIN IKUT BERUBAH — MOHON SEGERA DICEK', bNomor(true), bVerif(),
  bagian('🔎 Data yang ikut berubah', ...berubah.map(kk => (NAMA_ISIAN[kk] || kk) + ': "' + String(awal[kk] == null ? '' : awal[kk]).slice(0, 60) + '" ➜ "' + String(akhir[kk] == null ? '' : akhir[kk]).slice(0, 60) + '"'),
    ...lain.map(kk => kk + ': "' + String(rA[kk] == null ? '' : rA[kk]).slice(0, 60) + '" ➜ "' + String(rZ[kk] == null ? '' : rZ[kk]).slice(0, 60) + '"')),
  bagian('🛠️ Tindakan tim', 'Kembalikan data di atas di billing ' + (g.billing_nama || 'Sky Tech')), bKontak());
if (hpAkhir !== lokal(g.baru)) return gagal('billing menjawab berhasil, tapi nomor yang tersimpan ' + hp(hpAkhir));
const rekap = memo.gantiHpHasil.filter(x => x && Date.now() - x.t < 30 * 864e5 && !(x.berubah || []).length).length;
return kirim('✅ NOMOR PELANGGAN BERHASIL DIPERBARUI', bNomor(true), bVerif(),
  bagian('🧾 Hasil di billing', 'Nomor HP tersimpan dan sudah dicek ulang ✅', 'Nama, email, NIK, dan alamat tidak berubah ✅', 'Isian lain (' + Object.keys(rA).length + ' data, termasuk data layanan / ODC / ODP bila ada) tidak berubah ✅'),
  bKontak(), bagian('📊 Rekap', 'Nomor diperbarui otomatis dalam 30 hari terakhir: ' + rekap));

// TOKEN BILLING MITRA (Surya, Bayu) - aplikasi billing sama dengan Sky Tech, akun bot sama untuk kedua mitra.
// Login hanya bila token belum ada / hampir habis. Login gagal -> dicoba lagi 30 menit kemudian (chat tetap jalan, billing mitra dilewati).
// Billing mitra yang dipakai diatur di node PROMPT CS -> BILLING_MITRA (kosongkan [] untuk mematikan).
