// SIMPAN TOKEN BILLING MITRA: hasil node "Login billing mitra" (urutannya sama dengan item dari node "Token mitra")
// Token disimpan di memo.tokenMitra[kode]; password tidak pernah lewat sini (dipasang di kredensial n8n).
const memo = $getWorkflowStaticData('global');
memo.tokenMitra = memo.tokenMitra || {};
