  const kd = asal && asal.json && asal.json.kode;
  if (!kd) return;
  const r = h.json || {};
  const tk = r.data && r.data.token;
  if (tk) memo.tokenMitra[kd] = { token: tk, exp: now + (Number(r.data.expires_in) || 604800) * 1000 - 3600e3 };
  else {
