    const r = await http.httpRequest({ method: 'GET', url: ACS + '/faults/?query=' + encodeURIComponent(JSON.stringify({ device: a.device_id })), json: true, timeout: 10000, ignoreHttpStatusErrors: true });
    return (Array.isArray(r) ? r : []).sort((x, y) => Date.parse(y.timestamp || 0) - Date.parse(x.timestamp || 0)).slice(0, 2)
