};
const hapusTugas = async id => { if (!id) return; try { await http.httpRequest({ method: 'DELETE', url: ACS + '/tasks/' + encodeURIComponent(id), timeout: 10000, ignoreHttpStatusErrors: true }); log.push('tugas ' + id + ' yang tertahan dihapus dari antrean ACS'); } catch (e) { /* abaikan */ } };
// 202 = modem belum selesai menjawab: cek apakah ada FAULT untuk tugas itu (ditolak) atau sekadar antre
const nasib = async r => {
  if (r.kode === 200) return { ok: true };
