  const target = slots.filter(s => s.aktif && diminta.includes(sama(s.ssid)));
  // sandi: pilihan pelanggan (sudah divalidasi di Baca keputusan) atau dibuat sistem: kata sederhana + 4 angka, mudah diketik
  const KATA = ['Mawar', 'Melati', 'Kenanga', 'Anggrek', 'Kelapa', 'Mangga', 'Durian', 'Pisang', 'Jambu', 'Nanas', 'Salak', 'Rambutan', 'Bintang', 'Pelangi', 'Samudra', 'Gunung', 'Sawah', 'Kopi', 'Langit', 'Embun', 'Cemara', 'Merpati', 'Kenari', 'Elang', 'Rajawali', 'Kancil', 'Gajah', 'Harimau', 'Lumba', 'Teratai', 'Matahari', 'Bulan', 'Pantai', 'Danau', 'Sungai', 'Bambu', 'Jati', 'Beringin', 'Cendana', 'Pandan', 'Jeruk', 'Apel', 'Anggur', 'Semangka', 'Manggis', 'Kedondong', 'Sirsak', 'Alpukat', 'Pepaya', 'Belimbing'];
  const acak = n => { try { const u = new Uint32Array(1); crypto.getRandomValues(u); return u[0] % n; } catch (e) { return Math.floor(Math.random() * n); } };
  const sandi = a.sandi || (KATA[acak(KATA.length)] + String(1000 + acak(9000)));
  const gagalSandi = async (sebab, tindakan) => {
    catat('gagal');
    return keluar('⚠️ GANTI SANDI WIFI GAGAL', [bagian('❗ Penyebab', sebab), await bagianLog(true), bagian('🛠️ Tindakan tim', tindakan || 'Ganti sandi manual dari Panel ACS, lalu kirim sandinya ke pelanggan di chat')],
      'Maaf Kak, sandi WiFi-nya belum berhasil kami ganti otomatis 🙏\n\nTim kami bantu dari sini ya, mohon ditunggu sebentar.');
  };
  if (!slots.length) return gagalSandi('konfigurasi WiFi modem tidak terbaca (baca ulang: ' + segar.kode + ')');
  if (!target.length) return gagalSandi('nama WiFi yang dikonfirmasi pelanggan (' + a.ssid.join(', ') + ') tidak ada di SSID aktif modem: ' + (slots.filter(s => s.aktif).map(s => s.ssid + ' (' + s.band + 'G)').join(', ') || '-'));
  const terbuka = target.filter(s => /^(basic|none)$/i.test(String(nilai(s.w.BeaconType) || '')));
  if (terbuka.length) return gagalSandi('SSID ' + terbuka.map(s => s.ssid).join(', ') + ' tanpa keamanan (open); perlu diatur ke WPA2 dulu', 'Atur keamanan WPA2 dan sandi dari Panel ACS, lalu kirim sandinya ke pelanggan');
  const susunParam = (pilih) => target.flatMap(s => pilih.filter(k => tulisBisa(s.w, k) || (k === 'PreSharedKey.1.KeyPassphrase' && s.w.PreSharedKey && s.w.PreSharedKey['1'] && tulisBisa(s.w.PreSharedKey['1'], 'KeyPassphrase')))
    .map(k => [WLAN + '.' + s.i + '.' + k, sandi, 'xsd:string']));
  let r = null, h = null;
  const sebab = [];
  for (const pilih of [['KeyPassphrase', 'PreSharedKey.1.KeyPassphrase'], ['KeyPassphrase'], ['PreSharedKey.1.KeyPassphrase']]) {
    const p = susunParam(pilih);
    if (!p.length) continue;
    r = await tugas({ name: 'setParameterValues', parameterValues: p }, 30000);
    h = await nasib(r);
    if (h.ok) break;
    if (h.antre) await hapusTugas(r.id); // sandi baru hanya dikirim ke pelanggan bila PASTI sudah diterapkan
    sebab.push(pilih.join(' + ') + ': ' + h.sebab);
  }
  if (!r) return gagalSandi('parameter sandi WiFi tidak ditemukan / tidak bisa ditulis di modem ini');
  if (!h.ok) return gagalSandi('modem tidak menerapkan sandi baru (' + sebab.join('; ') + ')');
  catat('berhasil');
  const nm = target.map(s => s.ssid);
  const namaWifi = [...new Set(nm)].map(x => '*' + x + '*').join(' dan ');
  const pesan = [
    'Sandi WiFi ' + namaWifi + ' sudah kami ganti ya Kak 🔐',
    '',
    'Sandi baru: *' + sandi + '*',
    '',
    'Semua HP dan perangkat akan terputus sebentar. Sambungkan lagi ke WiFi ' + namaWifi + ' dengan sandi baru di atas (pilih "Lupakan jaringan" dulu bila HP tidak mau tersambung).',
    'Simpan sandinya baik-baik dan jangan dibagikan ke orang lain ya Kak 🙏'
  ].join('\n');
  return keluar('🔐 SANDI WIFI PELANGGAN DIGANTI', [bagian('🧾 Hasil', 'SSID: ' + nm.join(', ') + ' (slot ' + target.map(s => s.i).join(', ') + ')', '✅ Diterima dan diterapkan modem', 'Sandi baru dikirim langsung ke pelanggan di chat (tidak ditampilkan di sini)'), bagian('🧾 Log ACS', ...log.slice(-6))], pesan);
}

// ======================= LEBAR KANAL =======================
// tipe & param setelan per slot (urutan sama dengan Panel ACS: channelWidthParam)
const tipeLebar = w => tulisBisa(w, 'X_HW_HT20') ? { tipe: 'hwht20', param: 'X_HW_HT20' }
  : tulisBisa(w, 'X_CMCC_ChannelWidth') ? { tipe: 'xcmcc', param: 'X_CMCC_ChannelWidth' }
  : tulisBisa(w, 'X_CT-COM_ChannelWidth') ? { tipe: 'ctcom', param: 'X_CT-COM_ChannelWidth' }
  : tulisBisa(w, 'OperatingChannelBandwidth') ? { tipe: 'standard', param: 'OperatingChannelBandwidth' }
  : tulisBisa(w, 'X_ZTE-COM_OperatingChannelBandwidth') ? { tipe: 'ztecom', param: tulisBisa(w, 'BandWidth') ? 'BandWidth' : 'X_ZTE-COM_OperatingChannelBandwidth' }
  : tulisBisa(w, 'BandWidth') ? { tipe: 'bwstr', param: 'BandWidth' }
  : null;
// nilai setelan -> '20' / '40' / '80' / '160' / 'auto' / 'auto5'
const normal = (tipe, x, band) => {
  if (x === undefined || x === null || x === '') return '';
  const t = String(x).trim();
  if (tipe === 'hwht20') return { '0': 'auto', '1': '20', '2': '40', '3': 'auto5' }[t] || '';
  if (tipe === 'xcmcc' || tipe === 'ctcom') return Object.keys(KODE).find(nm => String(KODE[nm]) === t) || '';
  if (/^auto/i.test(t)) return band === '5' ? 'auto5' : 'auto';
  return (t.match(/^(20|40|80|160)\s*m/i) || [])[1] || '';
};
// nilai yang ditulis untuk target tertentu
const nilaiTulis = (tipe, target, band, contoh) => {
  if (tipe === 'hwht20') return { auto: 0, '20': 1, '40': 2, auto5: 3 }[target];
  if (tipe === 'xcmcc' || tipe === 'ctcom') return band === '5' ? undefined : (target === 'auto5' ? undefined : Number(KODE[target]));
  if (target === 'auto' || target === 'auto5') return 'Auto';
  return target + (/Mhz$/.test(String(contoh || '')) ? 'Mhz' : 'MHz');
};
const rencana = a.aksi === 'lebar_kanal_auto' ? [{ band: '2.4', target: ['auto'] }] : [{ band: '2.4', target: ['40'] }, { band: '5', target: ['80', 'auto5'] }];
const laporan = [];
let adaGagal = false, adaUbah = false;
if (!slots.length) {
  adaGagal = true;
  laporan.push(bagian('📶 WiFi', '❌ konfigurasi WiFi modem tidak terbaca dari ACS (baca ulang: ' + segar.kode + ')'));
}
for (const rc of rencana) {
  const diBand = slots.filter(s => s.band === rc.band);
  if (!diBand.length) { if (rc.band === '2.4') { adaGagal = true; laporan.push(bagian('📶 WiFi 2.4 GHz', '❌ slot WiFi 2.4 GHz tidak ditemukan')); } continue; }
  const wakil = diBand.find(s => s.aktif) || diBand[0];
  const tl = tipeLebar(wakil.w);
  const judul = '📶 WiFi ' + (rc.band === '5' ? '5 GHz' : '2.4 GHz') + ' (' + (wakil.ssid || 'slot ' + wakil.i) + ')';
  // ZL-4224X: lebar kanal 5 GHz belum dipetakan di Panel ACS (tabel Pak Tobing 12 Nov) -> jangan menulis nilai tebakan; dilaporkan sebagai gagal
  if (rc.band === '5' && kelas === 'ZL-4224X') { adaGagal = true; laporan.push(bagian(judul, '❌ lebar kanal 5 GHz untuk ZL-4224X belum dipetakan di Panel ACS: tidak diubah otomatis (supaya tidak menulis nilai yang salah)')); continue; }
  if (!tl) { adaGagal = rc.band === '2.4' || adaGagal; laporan.push(bagian(judul, '❌ parameter lebar kanal yang bisa ditulis tidak ditemukan di modem ini')); continue; }
  const asli = nilai(wakil.w[tl.param]);
  const lama = normal(tl.tipe, asli, rc.band);
  const jalanAsli = nilai(wakil.w['X_ZTE-COM_OperatingChannelBandwidth']) ?? nilai(wakil.w.X_HW_CurrentOperatingChannelBandwidth);
  // 5G sudah 80 MHz ke atas (atau auto 80/40/20 di Huawei): biarkan
  if (rc.band === '5' && (['80', '160'].includes(lama) || (tl.tipe === 'hwht20' && lama === 'auto5'))) { laporan.push(bagian(judul, 'ℹ️ sudah ' + NAMA_LEBAR[lama] + ' (' + tl.param + ' = ' + asli + '), tidak diubah')); continue; }
  if (rc.target.includes(lama) && rc.target[0] === lama) { laporan.push(bagian(judul, 'ℹ️ sudah ' + NAMA_LEBAR[lama] + ' (' + tl.param + ' = ' + asli + '), tidak diubah' + (jalanAsli && normal('bwstr', jalanAsli, rc.band) !== lama ? '; radio berjalan di ' + jalanAsli : ''))); continue; }
  let berhasil = null;
  const catatan = [];
  for (const tg of rc.target) {
    const v = nilaiTulis(tl.tipe, tg, rc.band, asli);
    if (v === undefined) { catatan.push('kode ' + tl.param + ' untuk ' + NAMA_LEBAR[tg] + ' di band ini belum dipetakan'); continue; }
    // tulis ke SEMUA slot di band ini yang punya param yang sama (radio fisik satu), seperti Panel ACS
    const p = diBand.filter(s => tulisBisa(s.w, tl.param)).map(s => [WLAN + '.' + s.i + '.' + tl.param, v, typeof v === 'number' ? 'xsd:unsignedInt' : 'xsd:string']);
    let r = await tugas({ name: 'setParameterValues', parameterValues: p }, 30000);
    let n = await nasib(r);
    if (n.antre) { berhasil = { tg, v, antre: true }; break; }
    if (!n.ok && p.length > 1) { catatan.push('semua slot: ' + n.sebab + '; dicoba slot utama saja'); r = await tugas({ name: 'setParameterValues', parameterValues: p.filter(x => x[0] === WLAN + '.' + wakil.i + '.' + tl.param) }, 30000); n = await nasib(r); }
    if (n.antre) { berhasil = { tg, v, antre: true }; break; }
    if (n.ok) { berhasil = { tg, v }; break; }
    catatan.push(NAMA_LEBAR[tg] + ' ditolak modem: ' + n.sebab);
  }
  if (!berhasil) { adaGagal = true; laporan.push(bagian(judul, '❌ gagal diubah dari ' + (NAMA_LEBAR[lama] || 'nilai ' + asli), ...catatan)); continue; }
  if (berhasil.antre) { laporan.push(bagian(judul, '⏳ perintah ' + NAMA_LEBAR[berhasil.tg] + ' antre di ACS (modem belum menjawab); diterapkan saat modem lapor berikutnya', ...catatan)); continue; }
  adaUbah = true;
  laporan.push(bagian(judul, '✅ ' + (NAMA_LEBAR[lama] || 'nilai ' + (asli === undefined ? 'belum terbaca' : asli)) + ' ➜ ' + NAMA_LEBAR[berhasil.tg] + ' (' + tl.param + ' = ' + berhasil.v + ', ' + diBand.filter(s => tulisBisa(s.w, tl.param)).length + ' slot)', ...catatan));
  berhasil.tipe = tl.tipe; berhasil.param = tl.param; berhasil.wakil = wakil.i;
  rc.hasil = berhasil;
}
// verifikasi: ONU me-restart WiFi setelah lebar kanal diubah, jadi baca ulang setelah jeda
if (adaUbah) {
  await tidur(JEDA_CEK);
  await tugas({ name: 'refreshObject', objectName: WLAN }, 30000);
  const w1 = await bacaWlan();
  for (const rc of rencana.filter(x => x.hasil)) {
    const ws = w1[String(rc.hasil.wakil)] || {};
    const kini = normal(rc.hasil.tipe, nilai(ws[rc.hasil.param]), rc.band);
    const jalan = nilai(ws['X_ZTE-COM_OperatingChannelBandwidth']) ?? nilai(ws.X_HW_CurrentOperatingChannelBandwidth);
    const L = laporan.find(x => x.judul.startsWith('📶 WiFi ' + (rc.band === '5' ? '5 GHz' : '2.4 GHz')));
    if (kini === rc.hasil.tg) L.isi.push('Dicek ulang: setelan sekarang ' + NAMA_LEBAR[kini] + ' ✅' + (jalan ? ', radio berjalan di ' + jalan : ''));
    else if (kini) { adaGagal = true; L.isi.push('Dicek ulang: setelan masih ' + (NAMA_LEBAR[kini] || kini) + ' ⚠️ (modem menerima perintah tapi mengabaikan nilainya)'); }
    else L.isi.push('Dicek ulang: nilai belum terbaca dari modem (WiFi mungkin masih restart)');
  }
}
catat(adaGagal ? (adaUbah ? 'sebagian' : 'gagal') : (adaUbah ? 'berhasil' : 'sudah sesuai'));
const judulAkhir = adaGagal ? '⚠️ AKSI PERANGKAT GAGAL / SEBAGIAN — LEBAR KANAL WIFI' : adaUbah ? '🛠️ AKSI PERANGKAT DIJALANKAN — LEBAR KANAL WIFI' : 'ℹ️ LEBAR KANAL SUDAH SESUAI — TIDAK DIUBAH';
// v45: pesan netral ke pelanggan (tanpa istilah teknis): 2.4 GHz gagal -> tim NOC; berhasil / sebagian -> diminta mencoba lagi
const gagal24 = laporan.some(L => /2\.4 GHz/.test(L.judul) && L.isi.some(x => /❌/.test(x))) || !slots.length;
const kabarGagal = gagal24 ? PESAN_GAGAL : (adaUbah ? PESAN_SELESAI : '');
if (!gagal24 && adaUbah && PESAN_SELESAI) await tidur(30000);
return keluar(judulAkhir, [...laporan, adaGagal ? await bagianLog(true) : bagian('🧾 Log ACS', ...log.slice(-8)), adaGagal ? bagian('🛠️ Tindakan tim', 'Cek dan ubah manual dari Panel ACS (menu Device → Radio), lalu kabari pelanggan di chat', gagal24 ? 'Pelanggan sudah dikabari otomatis: sedang dicek lebih lanjut oleh tim NOC' : 'Pelanggan TIDAK diberi tahu detail teknis; hanya diminta mencoba lagi internetnya') : null], kabarGagal);

// PANTAU PEMBAYARAN: setelah QRIS/VA dikirim, workflow "Pantau Pembayaran ULAN AI" mengecek status invoice tiap menit
// dan mengirim kabar "pembayaran berhasil" begitu lunas. Pengaturan PANTAU_BAYAR di node PROMPT CS.
// Bila pemantauan tidak bisa dimulai, pembayaran dikembalikan ke pengecekan terjadwal 10 menit (tanda pantau dihapus).
const memo = $getWorkflowStaticData('global');
const items = $input.all().map(i => i.json || {}).filter(j => j.ref && j.invoice && !j.gagal);
const kembalikan = daftarInv => {
  for (const v of Object.values(memo.bayarAi || {})) if (v && v.pantau && daftarInv.some(j => String(j.invoice) === String(v.inv) && String(j.conversation_id) === String(v.cid))) v.pantau = false;
  return [];
};
const ambil = (n, k) => { try { return (($(n).first() || {}).json || {})[k] || {}; } catch (e) { return {}; } };
try {
  const atur = ambil('PROMPT CS (edit di sini)', 'pengaturan');
  if (atur.PANTAU_BAYAR === false || atur.KABAR_BAYAR_BERHASIL === false) return kembalikan(items);
  if (!items.length) return [];
  const token = { SKY: (memo.billingToken && memo.billingToken.token) || '' };
  for (const [kd, v] of Object.entries(memo.tokenMitra || {})) if (v && v.token) token[kd] = v.token;
  const wh = ambil('Pesan masuk MobiChat', 'body');
  const ks = ambil('Susun konteks', 'kontak');
  const peta = new Map();
  const tanpaToken = [];
  for (const j of items) {
    const b = j.billing || 'SKY';
    if (!token[b]) { tanpaToken.push(j); continue; }
    const kk = b + ':' + j.invoice;
    if (!peta.has(kk)) peta.set(kk, { inv: String(j.invoice), b, url: String(j.billing_url || 'https://billing.btd.co.id').replace(/\/+$/, ''), ref: j.ref, metode: j.metode, total_bayar: j.total_bayar, periode: j.periode || '', sn: j.sn || '', nama: j.nama || '', exp: Number(j.exp) || 0 });
  }
  if (tanpaToken.length) kembalikan(tanpaToken);
  const daftar = [...peta.values()];
  if (!daftar.length) return [];
  const now = Date.now();
  const batas = Math.min(now + 6 * 3600e3, Math.max(...daftar.map(x => x.exp || now + 3600e3)) + 15 * 60e3);
  return [{ json: { cid: String(items[0].conversation_id), daftar, token, mobichat: String(wh.mobichat_base_url || 'https://app.mobichat.id').replace(/\/+$/, ''), kontak: ks.nama || '', mulai: now, batas, ke: 0 } }];
} catch (e) {
