const bolehB = (Array.isArray(atur.PELUNASAN_BILLING) ? atur.PELUNASAN_BILLING : PELUNASAN_BILLING).map(x => String(x).toUpperCase());
const kirimWa = atur.KIRIM_WA_BILLING != null ? atur.KIRIM_WA_BILLING !== false : KIRIM_WA_BILLING;
const ujiSaja = [].concat(Array.isArray(atur.ID_UJI_SAJA) ? atur.ID_UJI_SAJA : ID_UJI_SAJA).map(x => String(x).toUpperCase().replace(/[^A-Z0-9:]/g, '')).filter(Boolean);
const memo = $getWorkflowStaticData('global');
const now = Date.now();
const hariIni = new Date(now + 7 * 3600e3).toISOString().slice(0, 10);
memo.lunasAi = (memo.lunasAi && memo.lunasAi.hari === hariIni) ? memo.lunasAi : { hari: hariIni, n: 0, inv: (memo.lunasAi && memo.lunasAi.inv) || {} };
for (const [k, t] of Object.entries(memo.lunasAi.inv)) if (now - t > 40 * 864e5) delete memo.lunasAi.inv[k];
const ambilSemua = n => { try { return $(n).all().map(i => i.json || {}); } catch (e) { return []; } };
const asal = {}; for (const j of ambilSemua('Siapkan catatan struk')) if (j.KUNCI) asal[j.KUNCI] = j._info || {};
const dupl = ambilSemua('Cek duplikat struk');
const lengkap = {}; for (const j of dupl) if (j.KUNCI) lengkap[j.KUNCI] = j;
let profil = []; try { profil = ($('Cek tagihan billing').first().json || {}).profil || []; } catch (e) {}
const angka = x => String(x == null ? '' : x).replace(/\D/g, '');
const bersih = x => String(x == null ? '' : x).replace(/^'/, '').trim();
const rupiah = n => 'Rp' + String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const tidur = ms => new Promise(r => (typeof setTimeout === 'function' ? setTimeout(r, ms) : r()));
