// SAMPEL OLT HIOSO (CS) — mengurai halaman OLT HIOSO / HiSFocus EPON menjadi data ONU yang rapi untuk node "Cek tagihan billing"
// (format sama dengan OLT HSGQ), lalu menyimpan sampel penghitung putus per ONU tiap ±2 jam (HIOSO, untuk menghitung putus 24 jam).
// HIOSO (18 kolom per ONU): 0 id 0/slot/pon:onu, 1 nama, 2 MAC, 3 status (Up/PwrDown/...), 7 suhu, 10 TX, 11 RX,
//   13 jumlah putus kumulatif, 14 dying gasp (1 = mati listrik), 15 RTT (jarak = RTT x 1,6393 - 157 m), 16 jam online, 17 jam offline.
// HiSFocus (13 kolom per ONU, satu halaman per PON): 0 id, 1 nama, 2 MAC, 3 status (Up/Down), 4 versi, 5 chip, 6 jumlah port,
//   7 suhu, 10 TX, 11 RX, 12 RTT. Penyebab & jam putus dari System Log: "Nov 2 05:15:17 EPON: Onu 0/1/1:17 <MAC> dying-gasp",
//   "... Slot 0/1/1:17 Onu <MAC>[NAMA] Lost" (sinyal hilang), "... Onu 0/1/1:17 <MAC> [NAMA] Discovery" (menyala lagi).
//   Lost yang didahului dying-gasp (<= 60 detik) = listrik modem mati (Power down); Lost tanpa dying-gasp = LOS (sinyal fiber putus).
const memo = $getWorkflowStaticData('global');
const daftar = $('Daftar OLT HIOSO (CS)').all().map(i => i.json || {});
const hasil = $input.all().map(i => i.json || {});
const now = Date.now();
const teks = r => String(r.body != null ? r.body : r.data != null ? r.data : '');
const isiArray = (t, nama) => {
  let i = nama ? t.search(new RegExp('\\b' + nama + '\\s*=\\s*new Array\\(')) : -1;
  if (i < 0) i = t.indexOf('new Array('); if (i < 0) return [];
  const a = t.indexOf('(', i) + 1; const seg = t.slice(a, t.indexOf(');', a));
  const v = []; const re = /'([^']*)'|"([^"]*)"|(-?\d+(?:\.\d+)?)/g; let m;
  while ((m = re.exec(seg))) v.push(m[1] != null ? m[1] : m[2] != null ? m[2] : Number(m[3]));
  return v;
};
const baris = (v, n) => { const rows = []; for (let k = 0; k + n - 1 < v.length; k += n) rows.push(v.slice(k, k + n)); return rows; };
const angka = x => { const n = parseFloat(String(x == null ? '' : x)); return isFinite(n) && n > -40 ? n : null; };
// jam OLT (WIB) "2026-10-28 04:57:13"; jam sebelum OLT disinkronkan (tahun < 2026) diabaikan
const waktu = x => { const m = String(x || '').match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/); if (!m || +m[1] < 2026) return null; const t = Date.parse(m[1] + '-' + m[2] + '-' + m[3] + 'T' + m[4] + ':' + m[5] + ':' + m[6] + '+07:00'); return isFinite(t) && t <= now + 600e3 ? t : null; };
const jarakRtt = rtt => rtt > 0 ? Math.max(1, Math.round(rtt * 1.6393 - 157)) : null;
const idPon = id => { const m = String(id).match(/^\d+\/\d+\/(\d+):(\d+)$/); return m ? { pon: +m[1], ont: +m[2] } : { pon: 0, ont: 0 }; };
memo.hiosoCnt = (memo.hiosoCnt && typeof memo.hiosoCnt === 'object') ? memo.hiosoCnt : {};
memo.hiosoGagal = (memo.hiosoGagal && typeof memo.hiosoGagal === 'object') ? memo.hiosoGagal : {};
// baris System Log HiSFocus -> { t (ms, jam WIB OLT), id '0/1/1:17', ev 'dg' | 'lost' | 'naik' }
const BLN = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
const barisLog = t => t.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, '\n').split('\n').map(s => s.replace(/(&nbsp;|\s)+/g, ' ').trim()).map(s => {
  const m = s.match(/^([A-Za-z]{3})\s+(\d{1,2}) (\d\d):(\d\d):(\d\d)\s+(.*)$/); if (!m || BLN[m[1].toLowerCase()] == null) return null;
  const id = (m[6].match(/(\d+\/\d+\/\d+:\d+)/) || [])[1]; if (!id) return null;
  const ev = /dying-gasp/i.test(m[6]) ? 'dg' : /\bLost\b/i.test(m[6]) ? 'lost' : /Discovery/i.test(m[6]) ? 'naik' : ''; if (!ev) return null;
  const th = new Date(now + 7 * 3600e3).getUTCFullYear();
  let w = Date.UTC(th, BLN[m[1].toLowerCase()], +m[2], +m[3] - 7, +m[4], +m[5]);
  if (w > now + 864e5) w = Date.UTC(th - 1, BLN[m[1].toLowerCase()], +m[2], +m[3] - 7, +m[4], +m[5]);
  return { t: w, id, ev };
}).filter(Boolean);
// kelompokkan halaman per OLT (urutan sama dengan node daftar)
const grup = new Map();
daftar.forEach((o, k) => { if (!grup.has(o.ip)) grup.set(o.ip, { o, item: [] }); grup.get(o.ip).item.push({ o, r: hasil[k] || {} }); });
const keluar = [];
for (const { o, item } of grup.values()) {
  const dasar = { nama: o.nama, ip: o.ip, area: o.area };
  if (o.tipe === 'hisfocus') {
    const halPon = item.filter(z => z.o.bagian === 'pon');
    const okPon = halPon.filter(z => Number(z.r.statusCode) === 200);
    const rows = okPon.flatMap(z => baris(isiArray(teks(z.r), 'ponOnuTable'), 13)).filter(x => /^\d+\/\d+\/\d+:\d+$/.test(String(x[0])));
    if (!rows.length) {
      memo.hiosoGagal[o.ip] = now;
      const r0 = (halPon[0] || {}).r || {};
      keluar.push({ json: Object.assign(dasar, { ok: false, alasan: r0.error ? 'tidak terhubung' : 'status ' + (r0.statusCode || '-') }) });
      continue;
    }
    if (okPon.length === halPon.length && item.some(z => z.o.bagian === 'log')) delete memo.hiosoGagal[o.ip];
    const log = item.filter(z => z.o.bagian === 'log' && Number(z.r.statusCode) === 200).flatMap(z => barisLog(teks(z.r)));
    const per = {}; for (const e of log) (per[e.id] = per[e.id] || []).push(e);
    for (const k of Object.keys(per)) per[k].sort((a, b) => a.t - b.t);
    const awalLog = log.length ? Math.min(...log.map(e => e.t)) : null;
    const jamLog = awalLog ? Math.max(1, Math.min(24, Math.round((now - awalLog) / 3600e3))) : null;
    // satu kejadian putus = baris Lost (dying-gasp <= 60 detik sebelumnya = listrik), atau dying-gasp tanpa Lost
    const putusDari = ev => { const out = [];
      ev.forEach((e, i) => {
        if (e.ev === 'lost') out.push({ t: e.t, sebab: ev.some(d => d.ev === 'dg' && e.t - d.t >= 0 && e.t - d.t <= 60e3) ? 'Power down' : 'LOS' });
        else if (e.ev === 'dg' && !ev.some(l => l.ev === 'lost' && l.t - e.t >= 0 && l.t - e.t <= 60e3)) out.push({ t: e.t, sebab: 'Power down' });
      });
      return out; };
    const onu = rows.map(x => {
      const p = idPon(x[0]), up = String(x[3]) === 'Up', ev = per[String(x[0])] || [];
      const putus = putusDari(ev), naik = ev.filter(e => e.ev === 'naik');
      const akhirPutus = putus[putus.length - 1] || null, akhirNaik = naik[naik.length - 1] || null;
      const p24 = putus.filter(e => now - e.t < 864e5);
      return { pon: p.pon, ont: p.ont, nama: String(x[1] || '') === 'NA' ? '' : String(x[1] || ''), sn: String(x[2] || '').toLowerCase().replace(/[^0-9a-f]/g, ''),
        status: up ? 'online' : 'offline', st: String(x[3] || ''), rx: up ? angka(x[11]) : null, jarak: jarakRtt(Number(x[12]) || 0),
        sebab: akhirPutus ? akhirPutus.sebab : '', // modem online: penyebab putus TERAKHIR (sama seperti OLT HSGQ)
        t_turun: akhirPutus ? akhirPutus.t : null, t_naik: up && akhirNaik ? akhirNaik.t : null,
        putus24: jamLog ? { n: p24.length, jam: jamLog, power: p24.filter(e => e.sebab === 'Power down').length, laser: p24.filter(e => e.sebab === 'LOS').length } : null };
    });
    keluar.push({ json: Object.assign(dasar, { ok: true, tipe: 'hisfocus', t: now, onu, log_baris: log.length, pon_gagal: halPon.length - okPon.length }) });
    continue;
  }
  // ---- HIOSO (halaman All ONU List)
  const r = (item[0] || {}).r || {};
  const rows = Number(r.statusCode) === 200 ? baris(isiArray(teks(r)), 18) : [];
  if (!rows.length) { keluar.push({ json: Object.assign(dasar, { ok: false, alasan: r.error ? 'tidak terhubung' : 'status ' + (r.statusCode || '-') }) }); continue; }
  const onu = rows.map(x => {
    const p = idPon(x[0]); const up = String(x[3]) === 'Up'; const total = Number(x[13]) || 0;
    return { pon: p.pon, ont: p.ont, nama: String(x[1] || ''), sn: String(x[2] || '').toLowerCase().replace(/[^0-9a-f]/g, ''), status: up ? 'online' : 'offline', st: String(x[3] || ''),
      rx: up ? angka(x[11]) : null, jarak: jarakRtt(Number(x[15]) || 0), sebab: (!up || total) ? (Number(x[14]) === 1 || /pwr|power/i.test(x[3]) ? 'Power down' : 'LOS') : '',
      t_naik: waktu(x[16]), t_turun: waktu(x[17]), putus_total: total };
  });
  const s = memo.hiosoCnt[o.ip] = (Array.isArray(memo.hiosoCnt[o.ip]) ? memo.hiosoCnt[o.ip] : []).filter(z => z && now - z.t < 26 * 3600e3);
  if (!s.length || now - s[s.length - 1].t >= 115 * 60e3) s.push({ t: now, c: Object.fromEntries(onu.map(x => [x.pon + ':' + x.ont, x.putus_total])) });
  keluar.push({ json: Object.assign(dasar, { ok: true, t: now, onu }) });
}
return keluar;

