// CHAT MENUNGGU TIM (1/2) - jalan tiap 10 menit (cabang "Jadwal kabar gangguan").
// Chat yang sudah diteruskan AI ke tim, atau yang AI-nya diam (sedang ditangani CS, nomor / tag tanpa AI seperti DISABLE-AKSES AI),
// dicatat oleh node "Susun konteks" / "Perlu diteruskan ke tim?". Di sini dipilih yang sudah menunggu cukup lama, lalu riwayatnya
// dibaca dari MobiChat (node berikutnya) untuk memastikan belum dibalas siapa pun, sebelum tim diingatkan di Telegram.
// ===== PENGATURAN (edit di sini) =====
const PENGINGAT = {
  aktif: true,
  menit: 15,         // pengingat pertama setelah pelanggan menunggu sekian menit tanpa balasan
  ulang_menit: 60,   // pengingat berikutnya bila tetap belum dibalas
  maks: 3,           // paling banyak sekian pengingat per chat
  jam_mulai: 7,      // pengingat hanya dikirim pukul 07.00 - 21.00 WIB; chat malam diingatkan pagi harinya
  jam_selesai: 21
};
