for (const [cid, w] of Object.entries(memo.tungguChat)) if (!w || !w.sejak || now - w.sejak > 24 * 3600e3) delete memo.tungguChat[cid];
const jam = new Date(now + 7 * 3600e3).getUTCHours();
if (!PENGINGAT.aktif || jam < PENGINGAT.jam_mulai || jam >= PENGINGAT.jam_selesai) return [];
return Object.entries(memo.tungguChat)
  .filter(([cid, w]) => (w.n || 0) < PENGINGAT.maks && now - w.sejak >= PENGINGAT.menit * 60e3 && (!w.ingat || now - w.ingat >= PENGINGAT.ulang_menit * 60e3))
