const memo = $getWorkflowStaticData('global');
memo.tungguChat = memo.tungguChat || {};
const P = Object.assign({ maks: 3 }, memo.aturPengingat || {});
const now = Date.now();
const wib = t => { const w = new Date(t + 7 * 3600e3).toISOString(); return w.slice(8, 10) + '/' + w.slice(5, 7) + ' ' + w.slice(11, 16).replace(':', '.'); };
const jm = t => new Date(t + 7 * 3600e3).toISOString().slice(11, 16).replace(':', '.');
const lama = m => m < 60 ? Math.round(m) + ' menit' : Math.floor(m / 60) + ' jam' + (m % 60 >= 1 ? ' ' + Math.round(m % 60) + ' menit' : '');
