const teksPesan = m => { const t = String(m.text || m.message_text || '').replace(/\s+/g, ' ').trim(); const a = m.attachments || m.file_attachments || []; return (t || (a.length ? '[mengirim ' + (/image/.test(String((a[0] || {}).type || '')) ? 'foto' : 'lampiran') + ']' : '[pesan tanpa teks]')).slice(0, 120); };
// pesan penutup: hanya ucapan terima kasih / oke / emoji, tanpa pertanyaan dan tanpa lampiran
const KATA_TUTUP = new Set(('ok oke okey okay okee oce sip sipp siap baik ya iya y yaa iyaa nggih ngih njih injih inggih terima trima kasih makasih makasi mksh maksih '
  + 'thanks thank thx tq ty you u matur nuwun suwun alhamdulillah mantap mantab aman beres sudah udah dah done good kak ka kakak min admin mas mbak pak bu bang '
