  else Object.assign(t, { token: '', bad: false, gagal: r.error ? 'tidak terhubung' : 'login ditolak (' + (b && b.code != null ? b.code : (r.statusCode || '-')) + ')', gagal_t: now });
}
return [{ json: { kred: KRED, login: olt.map(o => o.ip + ' ' + (memo.oltTok[o.ip].token ? 'OK' : memo.oltTok[o.ip].gagal)) } }];

// DAFTAR SMARTOLT (CS) — OLT ZTE C300 dibaca lewat API SmartOLT tiap 10 menit (jalur jadwal), HANYA MEMBACA (GET).
