// Keadaan per eksekusi disimpan di memo.panelAksi[$execution.id].
// Alur sesuai dokumentasi panel: berhasil=true selesai | berhasil=null tunggu lalu GET /tasks/{id} (jangan kirim ulang) |
//   berhasil=false / antre terlalu lama -> DELETE /tasks/{id} lalu teruskan ke tim NOC.
// Pesan ke pelanggan TIDAK PERNAH memuat istilah teknis (lebar kanal, MHz, pita, reboot dari sistem); detail teknis hanya ke Telegram tim NOC.
const atur = ($('PROMPT CS (edit di sini)').first().json || {}).pengaturan || {};
const memo = $getWorkflowStaticData('global');
const exe = String($execution.id);
