const st = memo.panelAksi[exe];
if (!st || !st.a) return [];
const a = st.a;
const now = Date.now();
const tidur = ms => new Promise(r => setTimeout(r, ms));
const URL = String(atur.PANEL_ACS_URL || 'https://wifi.skytech.net.id/api/bot/v1').trim().replace(/\/+$/, '');
const JEDA_CEK = Number(atur.PANEL_JEDA_CEK_MS) >= 0 ? Number(atur.PANEL_JEDA_CEK_MS) : 45000;
const cid = String(a.cid || st.cid || '');
const enc = encodeURIComponent(a.device_id);
const tambahCid = p => p + (p.includes('?') ? '&' : '?') + 'conversation_id=' + encodeURIComponent(cid.slice(0, 64) || 'n8n');

// ---- jawaban node HTTP sebelumnya (fullResponse + neverError; galat jaringan -> json.error karena onError lanjut)
const r = $input.first().json || {};
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* biarkan teks */ } }
const kodeHttp = r.statusCode;
const galatJaringan = !kodeHttp ? String((r.error && (r.error.message || r.error.description)) || r.message || 'tidak ada jawaban').slice(0, 160) : '';
const err = body && typeof body === 'object' && body.ok === false ? (body.error || {}) : null;
const data = body && typeof body === 'object' && body.ok === true ? (body.data || {}) : null;
const langkah = st.langkah[st.i];
const req = st.req || {};
st.log.push(req.method + ' ' + String(req.url || '').replace(URL, '').replace(/[?&]conversation_id=[^&]*/, '') + ' → ' + (galatJaringan ? 'GAGAL TERHUBUNG (' + galatJaringan + ')'
  : 'HTTP ' + kodeHttp + (err ? ' ' + (err.code || '') + (err.alasan ? '/' + err.alasan : '') : '') + (data ? ' status=' + (data.status || (data.dihapus ? 'deleted' : '-')) + (data.berhasil !== undefined ? ' berhasil=' + data.berhasil : '') + (data.tidak_berubah ? ' tidak_berubah' : '') : '')));
st.log = st.log.slice(-14);

// ---- pembuat permintaan
const minta = async (kunci, method, path, isi, jeda) => {
  st.panggil = (st.panggil || 0) + 1;
