  if (l.jenis === 'reboot') return minta('aksi', 'POST', '/devices/' + enc + '/reboot', { idempotency_key: kunciIdem }, jeda);
  return minta('aksi', 'POST', '/devices/' + enc + '/channel-width', { band: l.band, width: l.width, idempotency_key: kunciIdem + (l.ganti ? '-b' : '') }, jeda);
};
