  MODE_AMAN: 'MODE AMAN panel aktif: semua perintah ke ONT dihentikan administrator', ACS_GAGAL: 'GenieACS menolak perintah', ACS_UNAVAILABLE: 'GenieACS tidak bisa dihubungi / ONT sedang dalam sesi',
  NOT_SUPPORTED: 'ONT / pita ini tidak didukung untuk diubah', INTERNAL_ERROR: 'galat di panel'
};
const ALASAN = { MODEL_RAPUH: 'model ONT ini rawan bila diubah (ditandai panel)', BELUM_DIPETAKAN: 'parameter model ini belum dipetakan di panel', TIDAK_ADA_PARAMETER: 'ONT tidak punya parameter lebar kanal',
  PITA_TIDAK_ADA: 'ONT tidak punya pita ini', LEBAR_TIDAK_TERSEDIA: 'lebar yang diminta tidak tersedia di model ini' };
const teksGalat = () => galatJaringan ? 'tidak terhubung ke Panel ACS (' + galatJaringan + ')'
  : err ? (err.code || 'GALAT') + ': ' + (ARTI[err.code] || err.message || '') + (err.alasan ? ' — ' + (ALASAN[err.alasan] || err.alasan) : '') + (err.message && ARTI[err.code] ? ' (' + String(err.message).slice(0, 120) + ')' : '')
